{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "intro_text",
        "context_heading",
        "context_text",
        "key_obligations_section_header",
        "business_structure_card",
        "california_registrations_card",
        "local_permits_card",
        "tax_obligations_card",
        "product_considerations_card",
        "resources_heading",
        "irs_button",
        "sos_button",
        "cdtfa_button",
        "ftb_button",
        "sources_heading",
        "cdtfa_source_button",
        "irs_source_button",
        "ftb_source_button",
        "sos_source_button"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "California E-commerce Jewelry Business Requirements",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Starting a small e-commerce business selling handmade jewelry in California involves several key legal and tax obligations. This guide outlines the necessary registrations, licenses, and basic tax requirements as of 2023."
      },
      "children": []
    },
    "context_heading": {
      "type": "Text",
      "props": {
        "text": "Context & Assumptions",
        "variant": "h2"
      },
      "children": []
    },
    "context_text": {
      "type": "Text",
      "props": {
        "text": "This information assumes you are operating as a small business based in California, selling directly to consumers via an online platform, and not hiring employees initially. It focuses on general state and federal requirements; local city/county requirements can vary significantly."
      },
      "children": []
    },
    "key_obligations_section_header": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "key_obligations_icon",
        "key_obligations_heading"
      ]
    },
    "key_obligations_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000862_01_1_clipboard-check.svg"
      },
      "children": []
    },
    "key_obligations_heading": {
      "type": "Text",
      "props": {
        "text": "Key Legal and Tax Obligations",
        "variant": "h2"
      },
      "children": []
    },
    "business_structure_card": {
      "type": "Card",
      "props": {},
      "children": [
        "business_structure_heading",
        "business_structure_text_1",
        "business_structure_text_2",
        "ein_apply_button"
      ]
    },
    "business_structure_heading": {
      "type": "Text",
      "props": {
        "text": "1. Business Structure & Federal ID",
        "variant": "h3"
      },
      "children": []
    },
    "business_structure_text_1": {
      "type": "Text",
      "props": {
        "text": "Choose a Business Entity: Decide on a legal structure such as Sole Proprietorship, Limited Liability Company (LLC), or Corporation. This choice impacts liability, taxation, and administrative burden."
      },
      "children": []
    },
    "business_structure_text_2": {
      "type": "Text",
      "props": {
        "text": "Employer Identification Number (EIN): Obtain from the IRS if you form an LLC or Corporation, or if you plan to hire employees. Sole proprietors can often use their Social Security Number but may opt for an EIN for business banking or privacy."
      },
      "children": []
    },
    "ein_apply_button": {
      "type": "Button",
      "props": {
        "label": "Apply for EIN",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/businesses/small-businesses-self-employed/apply-for-an-employer-identification-number-ein-online"
          }
        }
      },
      "children": []
    },
    "california_registrations_card": {
      "type": "Card",
      "props": {},
      "children": [
        "california_registrations_heading",
        "dba_text",
        "seller_permit_text",
        "seller_permit_button"
      ]
    },
    "california_registrations_heading": {
      "type": "Text",
      "props": {
        "text": "2. California State Registrations",
        "variant": "h3"
      },
      "children": []
    },
    "dba_text": {
      "type": "Text",
      "props": {
        "text": "Fictitious Business Name (DBA): If you operate as a Sole Proprietorship or Partnership under a name different from your legal personal name, you must register a Fictitious Business Name (Doing Business As) with your county clerk."
      },
      "children": []
    },
    "seller_permit_text": {
      "type": "Text",
      "props": {
        "text": "Seller's Permit: Required by the California Department of Tax and Fee Administration (CDTFA) to sell tangible goods. This allows you to collect sales tax from customers in California."
      },
      "children": []
    },
    "seller_permit_button": {
      "type": "Button",
      "props": {
        "label": "Register for Seller's Permit",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdtfa.ca.gov/taxes-and-fees/faqseller.htm"
          }
        }
      },
      "children": []
    },
    "local_permits_card": {
      "type": "Card",
      "props": {},
      "children": [
        "local_permits_heading",
        "city_county_license_text",
        "zoning_permits_text"
      ]
    },
    "local_permits_heading": {
      "type": "Text",
      "props": {
        "text": "3. Local Permits & Licenses",
        "variant": "h3"
      },
      "children": []
    },
    "city_county_license_text": {
      "type": "Text",
      "props": {
        "text": "City/County Business License: Most cities and counties in California require a local business license or permit to operate legally within their jurisdiction. Requirements and fees vary widely. Check with your specific city and county clerk's office."
      },
      "children": []
    },
    "zoning_permits_text": {
      "type": "Text",
      "props": {
        "text": "Zoning Permits: If you operate from a home address, verify local zoning regulations to ensure your home-based business complies, especially if you have significant inventory or customer traffic."
      },
      "children": []
    },
    "tax_obligations_card": {
      "type": "Card",
      "props": {},
      "children": [
        "tax_obligations_heading",
        "federal_income_tax_text",
        "state_income_tax_text",
        "sales_tax_text",
        "self_employment_tax_text",
        "estimated_taxes_text"
      ]
    },
    "tax_obligations_heading": {
      "type": "Text",
      "props": {
        "text": "4. Tax Obligations",
        "variant": "h3"
      },
      "children": []
    },
    "federal_income_tax_text": {
      "type": "Text",
      "props": {
        "text": "Federal Income Tax: Report your business income and expenses to the IRS. Sole proprietors typically use Schedule C (Form 1040). LLCs and Corporations have different reporting requirements."
      },
      "children": []
    },
    "state_income_tax_text": {
      "type": "Text",
      "props": {
        "text": "California State Income Tax: Report your business income and expenses to the California Franchise Tax Board (FTB)."
      },
      "children": []
    },
    "sales_tax_text": {
      "type": "Text",
      "props": {
        "text": "Sales Tax: Collect sales tax from customers located in California and remit it to the CDTFA. The tax rate varies by location."
      },
      "children": []
    },
    "self_employment_tax_text": {
      "type": "Text",
      "props": {
        "text": "Self-Employment Tax: If you are a sole proprietor or partner, you will pay self-employment taxes (Social Security and Medicare) on your net earnings."
      },
      "children": []
    },
    "estimated_taxes_text": {
      "type": "Text",
      "props": {
        "text": "Estimated Taxes: Both federal and state income taxes are generally paid quarterly if you expect to owe a certain amount of tax for the year."
      },
      "children": []
    },
    "product_considerations_card": {
      "type": "Card",
      "props": {},
      "children": [
        "product_considerations_heading",
        "product_safety_text",
        "prop_65_text"
      ]
    },
    "product_considerations_heading": {
      "type": "Text",
      "props": {
        "text": "5. Product-Specific Considerations",
        "variant": "h3"
      },
      "children": []
    },
    "product_safety_text": {
      "type": "Text",
      "props": {
        "text": "Product Safety: Ensure your handmade jewelry meets general product safety standards."
      },
      "children": []
    },
    "prop_65_text": {
      "type": "Text",
      "props": {
        "text": "Proposition 65 Warnings: If any materials used in your jewelry contain chemicals identified by California's Proposition 65 as causing cancer or reproductive harm, you may be required to provide a warning."
      },
      "children": []
    },
    "resources_heading": {
      "type": "Text",
      "props": {
        "text": "Essential Resources",
        "variant": "h2"
      },
      "children": []
    },
    "irs_button": {
      "type": "Button",
      "props": {
        "label": "IRS Small Business & Self-Employed Tax Center",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/businesses/small-businesses-self-employed"
          }
        }
      },
      "children": []
    },
    "sos_button": {
      "type": "Button",
      "props": {
        "label": "California Secretary of State - Business Programs",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.sos.ca.gov/business-programs"
          }
        }
      },
      "children": []
    },
    "cdtfa_button": {
      "type": "Button",
      "props": {
        "label": "California Department of Tax and Fee Administration (CDTFA)",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdtfa.ca.gov/"
          }
        }
      },
      "children": []
    },
    "ftb_button": {
      "type": "Button",
      "props": {
        "label": "California Franchise Tax Board (FTB)",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ftb.ca.gov/"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "cdtfa_source_button": {
      "type": "Button",
      "props": {
        "label": "California Department of Tax and Fee Administration",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.cdtfa.ca.gov/"
          }
        }
      },
      "children": []
    },
    "irs_source_button": {
      "type": "Button",
      "props": {
        "label": "Internal Revenue Service",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.irs.gov/"
          }
        }
      },
      "children": []
    },
    "ftb_source_button": {
      "type": "Button",
      "props": {
        "label": "California Franchise Tax Board",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.ftb.ca.gov/"
          }
        }
      },
      "children": []
    },
    "sos_source_button": {
      "type": "Button",
      "props": {
        "label": "California Secretary of State",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.sos.ca.gov/business-programs"
          }
        }
      },
      "children": []
    }
  }
}
